import{_ as t,o as e,c as s,ak as n}from"./chunks/framework.DKi5cyCJ.js";const m=JSON.parse('{"title":"插补与速度规划","description":"Bresenham、插补节拍和脉冲频率、多段轨迹的三级前瞻","frontmatter":{"title":"插补与速度规划","description":"Bresenham、插补节拍和脉冲频率、多段轨迹的三级前瞻","date":"2026-10-21T00:00:00.000Z"},"headers":[],"relativePath":"pages/blog/2026-10-21-插补与速度规划.md","filePath":"pages/blog/2026-10-21-插补与速度规划.md"}'),p={name:"pages/blog/2026-10-21-插补与速度规划.md"};function d(r,a,o,l,i,h){return e(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="插补与速度规划" tabindex="-1">插补与速度规划 <a class="header-anchor" href="#插补与速度规划" aria-label="Permalink to &quot;插补与速度规划&quot;">​</a></h1><blockquote><p>系列目录：<a href="/pages/blog/2026-10-20-嵌入式驱动面试手册.html">嵌入式驱动面试手册</a>。任务怎么摆见 <a href="/pages/blog/2026-10-21-RTOS线程与多轴.html">RTOS 线程与多轴</a>。</p></blockquote><p>步进电机只认脉冲。插补决定路径形状，速度规划决定走多快。两者合在一起，才是每个周期各轴发多少脉冲。</p><p>从 (0,0) 到 (10,3)，X 走 10 步、Y 走 3 步，同时起步、同时停。第一象限且 X 为主轴（dx ≥ dy ≥ 0）时，Bresenham 只用整数：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>err = 2*dy - dx</span></span>
<span class="line"><span>重复 dx 次：</span></span>
<span class="line"><span>  发一步 X</span></span>
<span class="line"><span>  若 err &gt; 0：发一步 Y，err = err + 2*dy - 2*dx</span></span>
<span class="line"><span>  否则：err = err + 2*dy</span></span></code></pre></div><p>(10,3) 的初始误差是 -4。Y 的 3 步摊在 10 步 X 里，折线偏差不超过半步。DDA 用累加器溢出分配脉冲，多轴和圆弧更直接，精度受累加器位宽限制。圆弧的脉冲增量法常用逐点比较：看当前点到圆心的距离平方和半径平方，决定往哪边迈一步。</p><p>DRV8711 这类步进驱动适合脉冲增量，或者 MotionTask 做粗插补、定时器做精插补。1 ms 里算出各轴该走的步数是粗插补；这一毫秒内由定时器均匀把脉冲发出去是精插补。浮点规划不要放进定时器中断。</p><h2 id="两个时间尺度" tabindex="-1">两个时间尺度 <a class="header-anchor" href="#两个时间尺度" aria-label="Permalink to &quot;两个时间尺度&quot;">​</a></h2><p>插补节拍是软件周期，例如 1 kHz。脉冲频率是 STEP 脚上的频率。慢的时候一个节拍可能不满一步，把小数累加，满 1 再发。快的时候一个节拍有几十步，定时器频率设成 <code>步数 / 1 ms</code>。速度由脉冲频率决定，不是由“每节拍固定走两步”决定。</p><p>步距 0.03125 mm 时，10 mm 用 1 秒走完，平均大约 320 Hz，1 ms 里只有 0.32 步。100 mm 用 0.1 秒走完，大约 32 kHz，1 ms 里约 32 步。上限还要看定时器、DRV8711 和电机能跟上的频率。</p><h2 id="多段轨迹要不要停" tabindex="-1">多段轨迹要不要停 <a class="header-anchor" href="#多段轨迹要不要停" aria-label="Permalink to &quot;多段轨迹要不要停&quot;">​</a></h2><p>几何上多段圆弧必须拆成多条段指令。执行时可以排队连续走，也可以每段停稳。</p><table tabindex="0"><thead><tr><th>级别</th><th>段边界</th><th>适合</th></tr></thead><tbody><tr><td>0</td><td>每段减速到 0 再走下一段</td><td>定位、注射泵、转盘。实现最简单</td></tr><tr><td>1</td><td>不停，衔接速度用一个保守固定值或查表</td><td>曲率变化不大的连续轨迹</td></tr><tr><td>2</td><td>按曲率和转角做双向速度传播</td><td>数控、激光。调试成本高</td></tr></tbody></table><p>内盘和注射泵保持 Level 0。XYZ 若只是走到点，也用 Level 0；若要连续画圆弧，从 Level 1 起步。业务任务只编排“先到 A 再转盘”，速度曲线全部留在 MotionTask。急停不经过前瞻：SafetyTask 置位后，MotionTask 每个节拍一进来就清空段队列。</p><p><a href="/pages/blog/2026-10-20-嵌入式驱动面试手册.html">返回目录</a></p>`,15)])])}const _=t(p,[["render",d]]);export{m as __pageData,_ as default};
